{
  "sop_id": "SOP-021",
  "title": "Employee Document Verification",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create and assign ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check completeness and legibility of documents",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify identity and address proofs",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Send education and employment confirmations to issuers or BGV agency",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Cross-check names, dates, grade, and salary against offer letter and HRMS",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Record verification status and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Credential confirmation (D1)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit",
      "role": "Executor",
      "type": "rework"
    },
    {
      "step_id": "A2",
      "name": "Lead approval (if discrepancies exist)",
      "role": "Lead",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "if discrepancies exist"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Issuer / BGV agency",
      "item": "Credential confirmation",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.90
}
